from pathlib import Path
import json, html, zipfile, xml.etree.ElementTree as ET

here = Path(__file__).parent
course = here.parents[2]
deckdir = here.parent / 'PacedDeck20261013'
deck = deckdir / 'output/Week_7_Paced_150_Minutes_v1.pptx'
source = json.loads((deckdir / 'slide_sources.json').read_text(encoding='utf-8-sig'))
ns = {'a':'http://schemas.openxmlformats.org/drawingml/2006/main'}
with zipfile.ZipFile(deck) as z:
    actual = []
    for n in range(1,72):
        e = ET.fromstring(z.read(f'ppt/slides/slide{n}.xml'))
        actual.append({'number':n,'hidden':e.get('show') == '0','text':[t.text or '' for t in e.findall('.//a:t',ns)]})

